-- Separate D1 billing schema. Better Auth core tables are installed by 0000_auth.sql.
CREATE TABLE IF NOT EXISTS billing_wallets (user_id TEXT PRIMARY KEY REFERENCES user(id), credits INTEGER NOT NULL DEFAULT 0 CHECK(credits BETWEEN 0 AND 1000000000), frozen INTEGER NOT NULL DEFAULT 0 CHECK(frozen IN (0,1)), unrecovered INTEGER NOT NULL DEFAULT 0 CHECK(unrecovered BETWEEN 0 AND 1000000000)) STRICT;
CREATE TABLE IF NOT EXISTS billing_subscriptions (user_id TEXT PRIMARY KEY REFERENCES user(id), status TEXT NOT NULL DEFAULT 'inactive' CHECK(status IN ('inactive','active','past_due','canceling','expired','canceled')), period_end TEXT, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS billing_ledger (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES user(id), delta INTEGER NOT NULL CHECK(delta != 0), kind TEXT NOT NULL, source TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL) STRICT;
CREATE INDEX IF NOT EXISTS billing_ledger_user_idx ON billing_ledger(user_id, created_at);
CREATE TRIGGER IF NOT EXISTS billing_ledger_immutable_update BEFORE UPDATE ON billing_ledger BEGIN SELECT RAISE(ABORT,'immutable ledger'); END;
CREATE TRIGGER IF NOT EXISTS billing_ledger_immutable_delete BEFORE DELETE ON billing_ledger BEGIN SELECT RAISE(ABORT,'immutable ledger'); END;
CREATE TABLE IF NOT EXISTS billing_report_receipts (user_id TEXT NOT NULL REFERENCES user(id), request_id TEXT NOT NULL, operation_id TEXT NOT NULL, input_digest TEXT NOT NULL, credits INTEGER NOT NULL CHECK(credits > 0), debited INTEGER NOT NULL CHECK(debited=1), created_at TEXT NOT NULL, PRIMARY KEY(user_id,request_id)) STRICT;
CREATE TABLE IF NOT EXISTS billing_verified_events (provider TEXT NOT NULL, event_id TEXT NOT NULL, event_digest TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES user(id), kind TEXT NOT NULL CHECK(kind IN ('pack-paid','pro-paid','pre-reversed','refund','pro-cancel-requested','pro-renewal-failed')), credits INTEGER NOT NULL CHECK(credits >= 0), reference_event_id TEXT, recovered INTEGER NOT NULL DEFAULT 0 CHECK(recovered>=0), deficit INTEGER NOT NULL DEFAULT 0 CHECK(deficit>=0), created_at TEXT NOT NULL, PRIMARY KEY(provider,event_id)) STRICT;
CREATE UNIQUE INDEX IF NOT EXISTS billing_one_refund_idx ON billing_verified_events(provider,reference_event_id) WHERE kind='refund';
CREATE TABLE IF NOT EXISTS billing_pending_reversals (provider TEXT NOT NULL, reference_event_id TEXT NOT NULL, event_id TEXT NOT NULL, event_digest TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES user(id), created_at TEXT NOT NULL, PRIMARY KEY(provider,reference_event_id), UNIQUE(provider,event_id)) STRICT;
CREATE TABLE IF NOT EXISTS billing_rate_limits (user_id TEXT NOT NULL REFERENCES user(id), window_start INTEGER NOT NULL, requests INTEGER NOT NULL CHECK(requests BETWEEN 1 AND 10), PRIMARY KEY(user_id,window_start)) STRICT;
CREATE TABLE IF NOT EXISTS billing_schema_version (version INTEGER PRIMARY KEY CHECK(version=1), applied_at TEXT NOT NULL) STRICT;
INSERT OR IGNORE INTO billing_schema_version VALUES (1,'2026-10-23T00:00:00.000Z');
